CREATE TABLE history_import_batch (history_import_batch_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), invocation_id TEXT NOT NULL UNIQUE, source_snapshot_hash TEXT NOT NULL UNIQUE, window_start TEXT NOT NULL, window_end TEXT NOT NULL, ordering_rule TEXT NOT NULL, source_rows_json TEXT NOT NULL, result_counts_json TEXT NOT NULL, quality_issues_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE history_import_source (history_import_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id), source_role TEXT NOT NULL, source_schema_version TEXT NOT NULL, object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), row_count INTEGER NOT NULL, PRIMARY KEY(history_import_batch_id,source_role));
CREATE TABLE account_event (account_event_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), event_date TEXT NOT NULL, source_order INTEGER NOT NULL, event_type TEXT NOT NULL, cash_effect INTEGER NOT NULL CHECK(cash_effect IN (0,1)), security_id TEXT REFERENCES security(security_id), quantity_decimal TEXT, price_decimal TEXT, amount_decimal TEXT NOT NULL, running_balance_decimal TEXT NOT NULL, aggregate_charges_inferred TEXT, canonical_row_hash TEXT NOT NULL, weak_row_identity TEXT NOT NULL, occurrence_ordinal INTEGER NOT NULL, source_object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), source_row_identity TEXT NOT NULL UNIQUE, created_by_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id));
CREATE TABLE account_transaction (account_transaction_id TEXT PRIMARY KEY, account_event_id TEXT NOT NULL UNIQUE REFERENCES account_event(account_event_id), side TEXT NOT NULL CHECK(side IN ('buy','sell')), quantity_decimal TEXT NOT NULL, price_decimal TEXT NOT NULL, gross_decimal TEXT NOT NULL, aggregate_charges_inferred TEXT NOT NULL, charges_status TEXT NOT NULL CHECK(charges_status='aggregate_charges_inferred'));
CREATE TABLE cash_ledger_entry (cash_ledger_entry_id TEXT PRIMARY KEY, account_event_id TEXT NOT NULL UNIQUE REFERENCES account_event(account_event_id), account_id TEXT NOT NULL REFERENCES account(account_id), event_date TEXT NOT NULL, amount_decimal TEXT NOT NULL, balance_decimal TEXT NOT NULL, source_row_identity TEXT NOT NULL UNIQUE);
CREATE TABLE holding_history_summary (holding_history_summary_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), security_id TEXT NOT NULL REFERENCES security(security_id), opened_on TEXT, closed_on TEXT, holding_days INTEGER, total_pnl_decimal TEXT, pnl_ratio_decimal TEXT, buy_average_decimal TEXT, sell_average_decimal TEXT, weak_row_identity TEXT NOT NULL, source_row_identity TEXT NOT NULL UNIQUE, source_object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), created_by_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id));
CREATE TABLE holding_history_revision (holding_history_revision_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), weak_row_identity TEXT NOT NULL, prior_summary_id TEXT NOT NULL REFERENCES holding_history_summary(holding_history_summary_id), candidate_row_hash TEXT NOT NULL, source_object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), status TEXT NOT NULL CHECK(status='conflict_pending'), created_by_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id), UNIQUE(account_id,weak_row_identity,candidate_row_hash));
CREATE TABLE history_source_revision (history_source_revision_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), weak_row_identity TEXT NOT NULL, prior_event_id TEXT NOT NULL REFERENCES account_event(account_event_id), candidate_row_hash TEXT NOT NULL, source_object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), status TEXT NOT NULL CHECK(status='conflict_pending'), created_by_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id), UNIQUE(account_id,weak_row_identity,candidate_row_hash));
CREATE TABLE account_history_quality_issue (history_quality_issue_id TEXT PRIMARY KEY, history_import_batch_id TEXT NOT NULL REFERENCES history_import_batch(history_import_batch_id), code TEXT NOT NULL, evidence_json TEXT NOT NULL);
CREATE TABLE account_history_snapshot (account_history_snapshot_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), history_import_batch_id TEXT NOT NULL UNIQUE REFERENCES history_import_batch(history_import_batch_id), as_of_date TEXT NOT NULL, event_count INTEGER NOT NULL, transaction_count INTEGER NOT NULL, cash_entry_count INTEGER NOT NULL, holding_summary_count INTEGER NOT NULL, reconciliation_status TEXT NOT NULL, limitations_json TEXT NOT NULL, created_at TEXT NOT NULL);
